1	import { DashboardHeader } from "@/components/dashboard/DashboardHeader";
2	import { AdminActivityTables } from "@/components/admin/AdminActivityTables";
3	import { requireRole } from "@/lib/auth";
4	import {
5	  listRecentSessions,
6	  listRecentPayments,
7	  listAllPayouts,
8	} from "@/lib/db/queries";
9	import { shortDate } from "@/lib/time";
10	import { t } from "@/lib/i18n";
11	
12	export const metadata = {
13	  title: `${t("admin.activityTitle")} · ${t("app.name")}`,
14	};
15	
16	export default async function AdminActivityPage() {
17	  await requireRole("admin");
18	  const [sessions, payments, payouts] = await Promise.all([
19	    listRecentSessions(25),
20	    listRecentPayments(25),
21	    listAllPayouts(25),
22	  ]);
23	
24	  return (
25	    <div className="flex flex-col gap-8">
26	      <DashboardHeader
27	        title={t("admin.activityTitle")}
28	        description={t("admin.activitySubtitle")}
29	      />
30	      <AdminActivityTables
31	        sessions={sessions.map((s) => ({
32	          id: s.id,
33	          dateLabel: shortDate(s.ended_at ?? s.created_at),
34	          dateMs: new Date(s.ended_at ?? s.created_at).getTime(),
35	          durationLabel: `${Math.floor(s.elapsed_seconds / 60)}:${String(
36	            s.elapsed_seconds % 60,
37	          ).padStart(2, "0")}`,
38	          totalCents: s.total_price_cents,
39	          commissionCents: s.commission_cents,
40	          earningsCents: s.provider_earnings_cents,
41	          status: s.status,
42	        }))}
43	        payments={payments.map((p) => ({
44	          id: p.id,
45	          dateLabel: shortDate(p.created_at),
46	          dateMs: new Date(p.created_at).getTime(),
47	          amountCents: p.amount_cents,
48	          status: p.status,
49	        }))}
50	        payouts={payouts.map((p) => ({
51	          id: p.id,
52	          periodLabel: `${shortDate(p.period_start)} – ${shortDate(p.period_end)}`,
53	          periodMs: new Date(p.period_end).getTime(),
54	          amountCents: p.amount_cents,
55	          status: p.status,
56	        }))}
57	      />
58	    </div>
59	  );
60	}
