1	"use client";
2	
3	import * as React from "react";
4	import { CircleCheck, Ban } from "lucide-react";
5	import { DataTable, type Column } from "@/components/ui/DataTable";
6	import { StatusBadge } from "@/components/ui/StatusBadge";
7	import { SuspendUserButton } from "@/components/admin/SuspendUserButton";
8	import { t } from "@/lib/i18n";
9	
10	export interface AdminUserRow {
11	  id: string;
12	  name: string;
13	  email: string;
14	  role: "customer" | "provider" | "admin";
15	  suspended: boolean;
16	}
17	
18	const ROLE_LABEL: Record<AdminUserRow["role"], "admin.roleCustomer" | "admin.roleProvider" | "admin.roleAdmin"> = {
19	  customer: "admin.roleCustomer",
20	  provider: "admin.roleProvider",
21	  admin: "admin.roleAdmin",
22	};
23	
24	export function UsersTable({ rows }: { rows: AdminUserRow[] }) {
25	  const columns: Column<AdminUserRow>[] = [
26	    { key: "name", header: t("admin.colName"), sortable: true },
27	    { key: "email", header: t("admin.colEmail") },
28	    {
29	      key: "role",
30	      header: t("admin.colRole"),
31	      sortable: true,
32	      render: (r) => t(ROLE_LABEL[r.role]),
33	    },
34	    {
35	      key: "suspended",
36	      header: t("admin.colState"),
37	      render: (r) =>
38	        r.suspended ? (
39	          <StatusBadge tone="alert" icon={Ban}>
40	            {t("admin.stateSuspended")}
41	          </StatusBadge>
42	        ) : (
43	          <StatusBadge tone="success" icon={CircleCheck}>
44	            {t("admin.stateActive")}
45	          </StatusBadge>
46	        ),
47	    },
48	    {
49	      key: "action",
50	      header: t("admin.colAction"),
51	      render: (r) =>
52	        r.role === "admin" ? (
53	          <span className="text-ink-soft">—</span>
54	        ) : (
55	          <SuspendUserButton userId={r.id} name={r.name} suspended={r.suspended} />
56	        ),
57	    },
58	  ];
59	
60	  return (
61	    <DataTable
62	      caption={t("admin.usersCaption")}
63	      columns={columns}
64	      rows={rows}
65	      getRowKey={(r) => r.id}
66	      emptyText={t("admin.usersNone")}
67	    />
68	  );
69	}
