1	"use client";
2	
3	import * as React from "react";
4	import {
5	  CircleCheck,
6	  Clock,
7	  RotateCcw,
8	  XCircle,
9	  PhoneCall,
10	  type LucideIcon,
11	} from "lucide-react";
12	import { DataTable, type Column } from "@/components/ui/DataTable";
13	import { StatusBadge, type StatusTone } from "@/components/ui/StatusBadge";
14	import { formatCents } from "@/lib/format";
15	import { t, type MessageKey } from "@/lib/i18n";
16	
17	export interface AdminSessionRow {
18	  id: string;
19	  dateLabel: string;
20	  dateMs: number;
21	  durationLabel: string;
22	  totalCents: number;
23	  commissionCents: number;
24	  earningsCents: number;
25	  status: string;
26	}
27	export interface AdminPaymentRow {
28	  id: string;
29	  dateLabel: string;
30	  dateMs: number;
31	  amountCents: number;
32	  status: string;
33	}
34	export interface AdminPayoutRow {
35	  id: string;
36	  periodLabel: string;
37	  periodMs: number;
38	  amountCents: number;
39	  status: string;
40	}
41	
42	/**
43	 * Status enum → { tone, localized label, paired icon }. Meaning is carried by
44	 * icon + human text together (never a raw DB token or colour alone), matching
45	 * the other status pills across the app.
46	 */
47	type StatusMeta = { tone: StatusTone; labelKey: MessageKey; icon: LucideIcon };
48	
49	const SESSION_STATUS: Record<string, StatusMeta> = {
50	  completed: { tone: "success", labelKey: "admin.sessCompleted", icon: CircleCheck },
51	  in_progress: { tone: "info", labelKey: "admin.sessInProgress", icon: PhoneCall },
52	  cancelled: { tone: "neutral", labelKey: "admin.sessCancelled", icon: XCircle },
53	};
54	const PAYMENT_STATUS: Record<string, StatusMeta> = {
55	  authorized: { tone: "neutral", labelKey: "admin.payAuthorized", icon: Clock },
56	  captured: { tone: "success", labelKey: "admin.payCaptured", icon: CircleCheck },
57	  refunded: { tone: "neutral", labelKey: "admin.payRefunded", icon: RotateCcw },
58	  failed: { tone: "alert", labelKey: "admin.payFailed", icon: XCircle },
59	};
60	const PAYOUT_STATUS: Record<string, StatusMeta> = {
61	  paid: { tone: "success", labelKey: "admin.payoutPaid", icon: CircleCheck },
62	  scheduled: { tone: "warning", labelKey: "admin.payoutScheduled", icon: Clock },
63	};
64	
65	function StatusCell({
66	  status,
67	  meta,
68	}: {
69	  status: string;
70	  meta: Record<string, StatusMeta>;
71	}) {
72	  const m = meta[status];
73	  if (!m) return <StatusBadge tone="neutral">{status}</StatusBadge>;
74	  return (
75	    <StatusBadge tone={m.tone} icon={m.icon}>
76	      {t(m.labelKey)}
