import * as React from "react";
import { t } from "@/lib/i18n";

/**
 * Editorial page header for the admin console: a small-caps "Admin" kicker
 * above the serif page title and a one-line lead (DESIGN_SPEC_V2 §3).
 */
export function AdminPageHeader({
  title,
  lead,
}: {
  title: string;
  lead?: string;
}) {
  return (
    <div className="flex flex-col gap-2">
      <p className="kicker">{t("admin.kicker")}</p>
    <h1 className="text-h1">{title}</h1>
      {lead ? <p className="max-w-prose text-lg text-ink-soft">{lead}</p> : null}
    </div>
  );
}

import * as React from "react";
import Link from "next/link";
import { ArrowRight } from "lucide-react";
import { StatCard } from "@/components/ui/StatCard";
import { t } from "@/lib/i18n";

/**
 * "Needs attention" tile for the admin overview. At zero it is a plain flat
 * StatCard; above zero the numeral turns alert-colored and the whole tile
 * becomes a link to the admin page where the problem is handled. State is
 * carried by the numeral color AND the visible "Review" link affordance —
 * never color alone (SPEC §10).
 */
export function AlertStatTile({
  label,
  value,
  alert,
  href,
}: {
  label: string;
  value: string | number;
  /** True when the metric needs action (> 0). */
  alert: boolean;
  /** Admin page that resolves the metric; used when `alert` is true. */
  href: string;
}) {
  if (!alert) return <StatCard label={label} value={value} />;

  return (
    <Link
      href={href}
      className="group flex flex-col gap-2 rounded-sm py-4 no-underline"
    >
      <span className="text-sm font-bold uppercase tracking-[0.12em] text-ink-soft">
        {label}
      </span>
      <span className="font-display text-h1 tabular-nums leading-none text-alert">
        {value}
      </span>
      <span className="inline-flex items-center gap-1.5 text-sm font-extrabold text-alert">
        {t("admin.alertReview")}
        <ArrowRight
          size={15}
          strokeWidth={2.25}
          aria-hidden="true"
          className="transition-transform duration-200 group-hover:translate-x-0.5"
        />
      </span>
    </Link>
  );
}

import * as React from "react";
import { StatCard } from "@/components/ui/StatCard";
import { AdminPageHeader } from "@/components/admin/AdminPageHeader";
import { AlertStatTile } from "@/components/admin/AlertStatTile";
import { requireRole } from "@/lib/auth";
import { getAdminMetrics } from "@/lib/db/queries";
import { getCommissionRate } from "@/lib/pricing";
import { formatCents } from "@/lib/format";
import { t } from "@/lib/i18n";

export const metadata = {
  title: `${t("admin.overviewTitle")} · ${t("app.name")}`,
};

const pct = (v: number | string | null) => `${Number(v ?? 0)}%`;
const n = (v: number | null) => v ?? 0;

/**
 * Hairline lattice for flat stat tiles: every cell draws its own top + left
 * hairline; the wrapper clips the outermost pair so only interior dividers
 * remain — no boxes, and uneven last rows stay clean (DESIGN_SPEC_V2 §4).
 */
function StatGrid({ children }: { children: React.ReactNode }) {
  return (
    <div className="overflow-hidden">
      <div className="-ml-px -mt-px grid grid-cols-3 max-md:grid-cols-2 max-sm:grid-cols-1 [&>*]:border-l [&>*]:border-t [&>*]:border-border [&>*]:px-6 [&>*]:py-2 max-sm:[&>*]:px-1">
        {children}
      </div>
    </div>
  );
}

export default async function AdminOverviewPage() {
  await requireRole("admin");
  const { strategic, operational, alerts } = await getAdminMetrics();

  return (
    <div className="flex flex-col gap-14 max-md:gap-10">
      <AdminPageHeader
        title={t("admin.overviewTitle")}
        lead={t("admin.overviewSubtitle")}
      />

      <section className="flex flex-col gap-4">
        <h2 className="kicker">{t("admin.strategicHeading")}</h2>
        <StatGrid>
          <StatCard label={t("admin.mGmv")} value={formatCents(n(strategic.gmv_cents))} />
          <StatCard label={t("admin.mRevenue")} value={formatCents(n(strategic.revenue_cents))} />
          <StatCard label={t("admin.mProviderEarnings")} value={formatCents(n(strategic.provider_earnings_cents))} />
          <StatCard label={t("admin.mActiveProviders")} value={n(strategic.active_providers)} />
          <StatCard label={t("admin.mActiveCustomers")} value={n(strategic.active_customers)} />
          <StatCard label={t("admin.mAvgRating")} value={Number(strategic.avg_rating ?? 0).toFixed(2)} />
        </StatGrid>
      </section>

      <section className="flex flex-col gap-4">
        <h2 className="kicker">{t("admin.operationalHeading")}</h2>
        <StatGrid>
          <StatCard label={t("admin.mConversion")} value={pct(operational.booking_to_session_pct)} />
          <StatCard label={t("admin.mActivation")} value={pct(operational.provider_activation_pct)} />
          <StatCard label={t("admin.mCompleted")} value={n(operational.completed_sessions)} />
          <StatCard label={t("admin.mAvailableNow")} value={n(operational.available_now)} />
          <StatCard label={t("admin.mOpenRequests")} value={n(operational.open_requests)} />
        </StatGrid>
      </section>

      <section className="flex flex-col gap-4">
        <h2 className="kicker">{t("admin.alertsHeading")}</h2>
        <StatGrid>
          <AlertStatTile
            label={t("admin.mApprovalBacklog")}
            value={n(alerts.approval_backlog)}
            alert={n(alerts.approval_backlog) > 0}
            href="/admin/providers"
          />
          <AlertStatTile
            label={t("admin.mOpenReports")}
            value={n(alerts.open_reports)}
            alert={n(alerts.open_reports) > 0}
            href="/admin/reports"
          />
          <AlertStatTile
            label={t("admin.mSuspended")}
            value={n(alerts.suspended_providers)}
            alert={n(alerts.suspended_providers) > 0}
            href="/admin/users"
          />
          <AlertStatTile
            label={t("admin.mCancellations")}
            value={pct(alerts.cancellation_pct)}
            alert={Number(alerts.cancellation_pct ?? 0) > 0}
            href="/admin/activity"
          />
          <AlertStatTile
            label={t("admin.mCancelled")}
            value={n(alerts.cancelled_bookings)}
            alert={n(alerts.cancelled_bookings) > 0}
            href="/admin/activity"
          />
          <AlertStatTile
            label={t("admin.mFailedPayments")}
            value={n(alerts.failed_payments)}
            alert={n(alerts.failed_payments) > 0}
            href="/admin/activity"
          />
        </StatGrid>
      </section>

      <section className="flex flex-col gap-3 border-t border-border pt-8">
        <h2 className="kicker">{t("admin.configHeading")}</h2>
        <div className="flex flex-wrap items-baseline gap-x-6 gap-y-1">
          <span className="text-base font-bold text-ink">
            {t("admin.commissionLabel")}
          </span>
          <span className="font-display text-h3 tabular-nums text-ink">
            {(getCommissionRate() * 100).toFixed(1)}%
          </span>
        </div>
        <p className="max-w-prose text-sm text-ink-soft">{t("admin.configNote")}</p>
      </section>
    </div>
  );
}

"use client";

import * as React from "react";
import { useTransition } from "react";
import { Check, X, Ban, Clock, CircleCheck, XCircle } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Tag } from "@/components/ui/Tag";
import { Avatar } from "@/components/ui/Avatar";
import { Dialog } from "@/components/ui/Dialog";
import { StatusBadge, type StatusTone } from "@/components/ui/StatusBadge";
import { VoicePlayer } from "@/components/ui/VoicePlayer";
import { decideProvider } from "@/app/(admin)/admin/actions";
import { formatBlockPrice, formatRating } from "@/lib/format";
import { t } from "@/lib/i18n";
import { useToast } from "@/components/ui/Toast";
import { type ProviderRow } from "@/lib/supabase/types";
import { type LucideIcon } from "lucide-react";

type Decision = "approve" | "reject" | "suspend";

const STATUS: Record<
  ProviderRow["status"],
  { label: string; tone: StatusTone; icon: LucideIcon }
> = {
  approved: { label: t("admin.statusApproved"), tone: "success", icon: CircleCheck },
  pending: { label: t("admin.statusPending"), tone: "warning", icon: Clock },
  rejected: { label: t("admin.statusRejected"), tone: "alert", icon: XCircle },
  suspended: { label: t("admin.statusSuspended"), tone: "alert", icon: Ban },
};

/**
 * One listener in the approval queue — an elevated white row (elevation means
 * "this needs a decision"): avatar + name + status pill, the voice intro
 * inline (the thing being reviewed), topic/language tags, prices on a
 * hairline, and the decision buttons. Reject asks for confirmation in a
 * dialog before it fires.
 */
export function ProviderApprovalCard({
  provider,
  audioUrl,
}: {
  provider: ProviderRow;
  audioUrl: string | null;
}) {
  const [pending, startTransition] = useTransition();
  const [rejectOpen, setRejectOpen] = React.useState(false);
  const { announce, toast } = useToast();
  const status = STATUS[provider.status];

  function decide(decision: Decision) {
    startTransition(async () => {
      const res = await decideProvider({ providerId: provider.id, decision });
      if (!res.ok) {
        toast(t("admin.decisionError"), "alert");
        return;
      }
      const key =
        decision === "approve"
          ? "admin.approvedAnnounce"
          : decision === "reject"
            ? "admin.rejectedAnnounce"
            : "admin.suspendedAnnounce";
      announce(t(key, { name: provider.display_name }), true);
    });
  }

  return (
    <Card as="li" className="flex flex-col gap-5">
      <div className="flex flex-wrap items-center gap-4">
        <Avatar name={provider.display_name} color={provider.avatar_color} size={64} />
        <div className="min-w-0 flex-1">
          <div className="flex flex-wrap items-center gap-x-3 gap-y-1.5">
            <h3 className="text-h3">{provider.display_name}</h3>
            <StatusBadge tone={status.tone} icon={status.icon}>
              {status.label}
            </StatusBadge>
          </div>
          <p className="mt-1 text-sm font-bold text-ink-soft">
            {t("admin.bgCheckLabel")}: {provider.bg_check_status}
            {provider.rating_count > 0
              ? ` · ${formatRating(provider.rating_avg)} (${provider.rating_count})`
              : ""}
          </p>
        </div>
      </div>

      <VoicePlayer
        name={provider.display_name}
        intro={provider.bio}
        big
        audioUrl={audioUrl}
      />

      <dl className="flex flex-col gap-2.5 text-base">
        <div className="flex flex-wrap items-center gap-2">
          <dt className="text-sm font-bold uppercase tracking-[0.12em] text-ink-soft">
            {t("admin.topicsLabel")}
          </dt>
          {provider.topics.map((topic) => (
            <dd key={topic}>
              <Tag>{topic}</Tag>
            </dd>
          ))}
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <dt className="text-sm font-bold uppercase tracking-[0.12em] text-ink-soft">
            {t("admin.languagesLabel")}
          </dt>
          {provider.languages.map((language) => (
            <dd key={language}>
              <Tag>{language}</Tag>
            </dd>
          ))}
        </div>
      </dl>

      <div className="flex flex-wrap items-center justify-between gap-4 border-t border-border pt-4">
        <p className="font-display text-lg tabular-nums text-ink">
          {formatBlockPrice(provider.price_block_15_cents, 15)} ·{" "}
          {formatBlockPrice(provider.price_block_30_cents, 30)} ·{" "}
          {formatBlockPrice(provider.price_block_45_cents, 45)}
        </p>
        <div className="flex flex-wrap gap-3">
          {provider.status !== "approved" ? (
            <Button icon={Check} onClick={() => decide("approve")} disabled={pending}>
              {t("admin.approve")}
            </Button>
          ) : null}
          {provider.status === "pending" ? (
            <Button
              variant="ghost"
              icon={X}
              onClick={() => setRejectOpen(true)}
              disabled={pending}
            >
              {t("admin.reject")}
            </Button>
          ) : null}
          {provider.status !== "suspended" && provider.status !== "rejected" ? (
            <Button
              variant="ghost"
              icon={Ban}
              onClick={() => decide("suspend")}
              disabled={pending}
            >
              {t("admin.suspend")}
            </Button>
          ) : null}
        </div>
      </div>

      {rejectOpen ? (
        <Dialog
          open
          onClose={() => setRejectOpen(false)}
          title={t("admin.rejectDialogTitle", { name: provider.display_name })}
          footer={
            <>
              <Button variant="ghost" onClick={() => setRejectOpen(false)}>
                {t("admin.rejectDialogCancel")}
              </Button>
              <Button
                variant="danger"
                icon={X}
                disabled={pending}
                onClick={() => {
                  setRejectOpen(false);
                  decide("reject");
                }}
              >
                {t("admin.rejectDialogConfirm")}
              </Button>
            </>
          }
        >
          <p className="text-base text-ink">
            {t("admin.rejectDialogBody", { name: provider.display_name })}
          </p>
        </Dialog>
      ) : null}
    </Card>
  );
}

