"use client";

import * as React from "react";
import { useTransition } from "react";
import { Banknote } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { StatCard } from "@/components/ui/StatCard";
import { runWeeklyPayouts } from "@/app/(admin)/admin/actions";
import { t } from "@/lib/i18n";
import { useToast } from "@/components/ui/Toast";

/**
 * Weekly payout runner: a flat editorial row — kicker heading, two StatCards
 * (how much is scheduled, for how many listeners) beside the one primary
 * action. The result lands as a toast; the page revalidates so the numbers
 * refresh after a run.
 */
export function PayoutRunner({
  scheduledCount,
  scheduledAmountLabel,
}: {
  scheduledCount: number;
  scheduledAmountLabel: string;
}) {
  const [pending, startTransition] = useTransition();
  const { toast } = useToast();

  function run() {
    startTransition(async () => {
      const { count } = await runWeeklyPayouts();
      toast(t("admin.payoutsRan", { count }), "success");
    });
  }

  return (
    <section className="flex flex-col gap-4 border-y border-border py-6">
      <div className="flex flex-col gap-1">
        <h2 className="kicker">{t("admin.payoutsHeading")}</h2>
        <p className="max-w-prose text-base text-ink-soft">
          {t("admin.payoutsBody")}
        </p>
      </div>
      <div className="flex flex-wrap items-end justify-between gap-x-10 gap-y-4">
        <div className="flex flex-wrap gap-x-14 gap-y-2">
          <StatCard
            label={t("admin.payoutsScheduledCount")}
            value={scheduledCount}
          />
          <StatCard
            label={t("admin.payoutsScheduledAmount")}
            value={scheduledAmountLabel}
          />
        </div>
        <Button icon={Banknote} onClick={run} disabled={pending} className="mb-4">
          {pending ? t("ui.loading") : t("admin.runPayouts")}
        </Button>
      </div>
    </section>
  );
}

import { AdminPageHeader } from "@/components/admin/AdminPageHeader";
import { ProviderApprovalCard } from "@/components/admin/ProviderApprovalCard";
import { PayoutRunner } from "@/components/admin/PayoutRunner";
import { requireRole } from "@/lib/auth";
import {
  listProvidersByStatus,
  listDecidedProviders,
  listAllPayouts,
} from "@/lib/db/queries";
import { getVoiceIntroSignedUrl } from "@/lib/storage";
import { formatCents } from "@/lib/format";
import { t } from "@/lib/i18n";
import { type ProviderRow } from "@/lib/supabase/types";

export const metadata = { title: `${t("admin.title")} · ${t("app.name")}` };

async function withAudio(providers: ProviderRow[]) {
  return Promise.all(
    providers.map(async (provider) => ({
      provider,
      audioUrl: await getVoiceIntroSignedUrl(provider.voice_intro_path),
    })),
  );
}

export default async function AdminProvidersPage() {
  await requireRole("admin");
  const [pending, decided, payouts] = await Promise.all([
    listProvidersByStatus("pending"),
    listDecidedProviders(),
    listAllPayouts(200),
  ]);
  const [pendingWithAudio, decidedWithAudio] = await Promise.all([
    withAudio(pending),
    withAudio(decided),
  ]);
  const scheduled = payouts.filter((p) => p.status === "scheduled");
  const scheduledCents = scheduled.reduce((sum, p) => sum + p.amount_cents, 0);

  return (
    <div className="flex flex-col gap-12 max-md:gap-8">
      <AdminPageHeader title={t("admin.title")} lead={t("admin.subtitle")} />

      <PayoutRunner
        scheduledCount={scheduled.length}
        scheduledAmountLabel={formatCents(scheduledCents)}
      />

      <section className="flex flex-col gap-5">
        <h2 className="text-h2">{t("admin.pendingHeading")}</h2>
        {pendingWithAudio.length === 0 ? (
          <p className="font-display text-lg text-ink-soft">
            {t("admin.pendingNone")}
          </p>
        ) : (
          <ul className="flex flex-col gap-5">
            {pendingWithAudio.map(({ provider, audioUrl }) => (
              <ProviderApprovalCard
                key={provider.id}
                provider={provider}
                audioUrl={audioUrl}
              />
            ))}
          </ul>
        )}
      </section>

      <section className="flex flex-col gap-5">
        <h2 className="text-h2">{t("admin.otherHeading")}</h2>
        {decidedWithAudio.length === 0 ? (
          <p className="font-display text-lg text-ink-soft">
            {t("admin.otherNone")}
          </p>
        ) : (
          <ul className="flex flex-col gap-5">
            {decidedWithAudio.map(({ provider, audioUrl }) => (
              <ProviderApprovalCard
                key={provider.id}
                provider={provider}
                audioUrl={audioUrl}
              />
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

"use client";

import * as React from "react";
import { useTransition } from "react";
import { Check, Ban, CircleAlert, CircleCheck } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { StatusBadge } from "@/components/ui/StatusBadge";
import { resolveReport, setUserSuspended } from "@/app/(admin)/admin/actions";
import { t } from "@/lib/i18n";
import { useToast } from "@/components/ui/Toast";

export interface ReportItem {
  id: string;
  reason: string;
  status: "open" | "reviewed";
  whenLabel: string;
  reporterName: string;
  targetId: string | null;
  targetName: string | null;
}

/**
 * One safety report as a flat hairline row (the list supplies the dividers):
 * who/about + status pill, the reason as the prominent line, then the
 * resolution actions. No card box — DESIGN_SPEC_V2 §4.
 */
export function ReportCard({ report }: { report: ReportItem }) {
  const [pending, startTransition] = useTransition();
  const { announce, toast } = useToast();

  function review() {
    startTransition(async () => {
      const res = await resolveReport(report.id);
      if (!res.ok) {
        toast(t("admin.decisionError"), "alert");
        return;
      }
      announce(t("admin.reportReviewed"), true);
    });
  }

  function suspendTarget() {
    if (!report.targetId) return;
    startTransition(async () => {
      const res = await setUserSuspended({
        userId: report.targetId!,
        suspended: true,
      });
      if (!res.ok) {
        toast(t("admin.decisionError"), "alert");
        return;
      }
      announce(
        t("admin.userSuspended", { name: report.targetName ?? "user" }),
        true,
      );
    });
  }

  return (
    <li className="flex flex-col gap-3 py-7 first:pt-0">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <span className="text-sm font-bold uppercase tracking-[0.12em] text-ink-soft">
          {t("admin.reportReporter")}: {report.reporterName}
          {report.targetName ? (
            <>
              {" · "}
              {t("admin.reportTarget")}: {report.targetName}
            </>
          ) : null}
          {" · "}
          {t("admin.reportWhen")}: {report.whenLabel}
        </span>
        <StatusBadge
          tone={report.status === "open" ? "warning" : "success"}
          icon={report.status === "open" ? CircleAlert : CircleCheck}
        >
          {report.status === "open"
            ? t("admin.reportStatusOpen")
            : t("admin.reportStatusReviewed")}
        </StatusBadge>
      </div>

      <p className="max-w-prose font-display text-xl text-ink">
        {report.reason}
      </p>

      <div className="flex flex-wrap gap-3 pt-1">
        {report.status === "open" ? (
          <Button
            icon={Check}
            onClick={review}
            disabled={pending}
            aria-label={t("admin.reportReviewAria", { name: report.reporterName })}
          >
            {t("admin.reportReview")}
          </Button>
        ) : null}
        {report.targetId ? (
          <Button
            variant="danger"
            icon={Ban}
            onClick={suspendTarget}
            disabled={pending}
            aria-label={t("admin.reportSuspendTargetAria", {
              name: report.targetName ?? report.reporterName,
            })}
          >
            {t("admin.reportSuspendTarget")}
          </Button>
        ) : null}
      </div>
    </li>
  );
}

import { AdminPageHeader } from "@/components/admin/AdminPageHeader";
import { ReportCard } from "@/components/admin/ReportCard";
import { requireRole } from "@/lib/auth";
import { listReports, getProfilesByIds } from "@/lib/db/queries";
import { shortDate } from "@/lib/time";
import { t } from "@/lib/i18n";

export const metadata = { title: `${t("admin.reportsTitle")} · ${t("app.name")}` };

export default async function AdminReportsPage() {
  await requireRole("admin");
  const reports = await listReports();

  const ids = Array.from(
    new Set(
      reports.flatMap((r) => [r.reporter_id, r.target_id].filter(Boolean)),
    ),
  ) as string[];
  const profiles = await getProfilesByIds(ids);
  const nameFor = (id: string | null) =>
    (id && (profiles.get(id)?.full_name || profiles.get(id)?.email)) || "—";

  return (
    <div className="flex flex-col gap-8">
      <AdminPageHeader
        title={t("admin.reportsTitle")}
        lead={t("admin.reportsSubtitle")}
      />

      {reports.length === 0 ? (
        <p className="font-display text-lg text-ink-soft">
          {t("admin.reportsNone")}
        </p>
      ) : (
        <ul className="flex flex-col divide-y divide-border">
          {reports.map((r) => (
            <ReportCard
              key={r.id}
              report={{
                id: r.id,
                reason: r.reason,
                status: r.status,
                whenLabel: shortDate(r.created_at),
                reporterName: nameFor(r.reporter_id),
                targetId: r.target_id,
                targetName: r.target_id ? nameFor(r.target_id) : null,
              }}
            />
          ))}
        </ul>
      )}
    </div>
  );
}

